def max_accordion_length(s):
    n = len(s)
    max_length = -1

    # Iterate over all possible starting positions of '['
    for start in range(n):
        if s[start] == '[':
            # Find the first occurrence of ':' after '['
            colon_pos = s.find(':', start + 1)
            if colon_pos == -1:
                continue

            # Count the number of '|' between the two colons
            pipe_count = 0
            for i in range(colon_pos + 1, n):
                if s[i] == '|':
                    pipe_count += 1
                elif s[i] == ':':
                    break
                elif s[i] == ']':
                    break

            # Check if there is a closing colon and a closing bracket
            if s[i] == ':' and i < n - 1 and s[i + 1] == ']':
                # Calculate the length of the accordion
                accordion_length = 2 + pipe_count * 2
                max_length = max(max_length, accordion_length)

