def max_accordion_length(s):
    n = len(s)
    max_length = -1

    # Two pointers approach
    start = 0
    while start < n:
        if s[start] == '[':
            colon_count = 0
            bar_count = 0
            end = start + 1
            while end < n:
                if s[end] == ']':
                    if colon_count == 2:
                        # Found a valid accordion
                        max_length = max(max_length, end - start + 1)
                    break
                elif s[end] == ':':
                    colon_count += 1
                elif s[end] == '|':
                    if colon_count == 1:
                        bar_count += 1
                end += 1
        start += 1

    return max_length

